-- CONSULTA DE AUDITORÍA Y VERIFICACIÓN DE REGISTROS MASIVOS
SELECT 'PERSONA' AS Tabla, COUNT(*) AS Total_Registros FROM PERSONA
UNION ALL SELECT 'PACIENTE', COUNT(*) FROM PACIENTE
UNION ALL SELECT 'MEDICO', COUNT(*) FROM MEDICO
UNION ALL SELECT 'DEPARTAMENTO', COUNT(*) FROM DEPARTAMENTO
UNION ALL SELECT 'CITA', COUNT(*) FROM CITA
UNION ALL SELECT 'CONSULTA', COUNT(*) FROM CONSULTA
UNION ALL SELECT 'RECETA', COUNT(*) FROM RECETA
UNION ALL SELECT 'MEDICAMENTO', COUNT(*) FROM MEDICAMENTO
UNION ALL SELECT 'RECETA_MEDICAMENTO', COUNT(*) FROM RECETA_MEDICAMENTO;
GO
